import csv, io
max_rows = int(ARGS.get('max_rows') or 50)
raw = ARGS.get('text') or ''
p = ARGS.get('path')
if p:
    raw = open(p, encoding='utf-8', errors='replace').read()
rows = list(csv.reader(io.StringIO(raw)))
if not rows:
    print('空表')
else:
    head = rows[0]
    print('| ' + ' | '.join(head) + ' |')
    print('|' + '|'.join(['---'] * len(head)) + '|')
    for r in rows[1:max_rows+1]:
        print('| ' + ' | '.join(x.replace('|','\\|') for x in r) + ' |')
    if len(rows) - 1 > max_rows: print('…共 %d 行，已截断' % (len(rows)-1))

import os, re, unicodedata
def slug(s):
    s = unicodedata.normalize('NFKC', s).strip()
    s = re.sub(r'[\\/:*?"<>|\s]+', '-', s)
    s = re.sub(r'-{2,}', '-', s).strip('-')
    return s[:80] or 'untitled'
t = ARGS.get('title')
d = ARGS.get('dir')
if t:
    print(slug(t))
elif d and os.path.isdir(d):
    for name in sorted(os.listdir(d)):
        base, ext = os.path.splitext(name)
        new = slug(base) + ext
        if new != name: print('%s  →  %s' % (name, new))
    print('（仅预览，未改动）')
else:
    print('给 title 或 dir')
